export const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
export function random(s){s.rng=(Math.imul(s.rng,1664525)+1013904223)>>>0;return s.rng/4294967296}
export function createState(data,player='jihyo',seed=Date.now()){const s={version:2,day:1,todayActions:0,visited:["path"],rumors:[],phase:"idle",pending:null,history:[],sleepState:null,player,seed:Number(seed)||1,rng:(Number(seed)||1)>>>0,tick:0,location:'path',characters:{},relations:{},events:[],log:[],discovered:[],flags:{},world:{seal:80,fear:25,snakePower:40},inventory:{herb:3,coins:20,book:0},combat:null,ended:false,serial:0};for(const c of data.characters)s.characters[c.id]={...c,maxHp:c.hp,energy:60,maxEnergy:60,stability:75,humanity:20,status:'건강',memories:[],knowledge:[]};for(const a of data.characters)for(const b of data.characters)if(a.id!==b.id)s.relations[a.id+':'+b.id]={affection:10,trust:10,caution:35,fear:0,respect:10,attachment:0,hostility:a.id==='snake'?75:0,romance:0};s.world.snakePower+=Math.floor(random(s)*15);record(s,'하얀 유성이 숲에 떨어졌다. 연기가 걷히고, 백호와 지효의 시선이 처음으로 마주쳤다.','story',8);return s}
export function present(s){return Object.values(s.characters).filter(c=>c.id!==s.player&&c.location===s.location&&c.hp>0&&c.status!=='사망')}
export function record(s,text,type='story',importance=3,witnesses=null){const e={id:++s.serial,tick:s.tick,turn:s.pending?.turn??s.tick,day:s.day,text,type,importance};s.log.push(e);if(type!=='system'){for(const c of Object.values(s.characters))if(c.hp>0&&(witnesses?witnesses.includes(c.id):c.location===s.location)){c.memories.push({eventId:e.id,text,tick:s.tick,importance,source:'목격',reliability:1});if(c.memories.length>45)c.memories=c.memories.filter((m,i)=>m.importance>=7||i>=c.memories.length-25)}}return e}
export function check(s,stat,difficulty=55){const p=s.characters[s.player],chance=Math.round(clamp(70+(p[stat]||10)*2-difficulty+(p.status==='중상'?-20:0),5,95)),roll=1+Math.floor(random(s)*100);const margin=chance-roll;return{chance,roll,result:roll<=5?'대성공':roll>=96?'대실패':margin>=0?'성공':margin>=-15?'부분 성공':'실패',success:roll<=5||(roll<96&&margin>=-15)}}
export function relation(s,a,b,changes){const r=s.relations[a+':'+b];if(r)for(const[k,v]of Object.entries(changes))if(k in r)r[k]=clamp(r[k]+v)}
export function startCombat(s,name='산길의 사역마',id=null){if(s.combat||s.ended)return;const enemy=id?s.characters[id]:null;s.combat={name:enemy?.name||name,id,hp:enemy?.hp||65,maxHp:enemy?.maxHp||65,power:enemy?.power||14,distance:1,round:1,guard:false,cover:false,intent:'공격',stunned:false};record(s,`${s.combat.name}이 전투 태세를 취했다. 거리는 중거리다.`,'combat',7)}
function finish(s,outcome){const c=s.combat;if(c.id){s.characters[c.id].hp=Math.max(0,c.hp);if(c.hp<=0)s.characters[c.id].status='기절'}record(s,outcome,'combat',8);s.combat=null;s.lastBattleOutcome=outcome.includes('의식을')?'defeat':outcome.includes('추격을')?'fled':outcome.includes('휴전')?'truce':'victory'}
export function combatAction(s,type,target){const c=s.combat,p=s.characters[s.player];if(!c||s.ended)return false;let text='',r=null;if(type==='attack'||type==='skill'){const max=type==='attack'?0:1,cost=type==='skill'?12:0;if(c.distance>max){record(s,'사거리가 닿지 않습니다. 먼저 접근하세요.','system');return false}if(p.energy<cost){record(s,'기력이 부족합니다.','system');return false}p.energy-=cost;r=check(s,'power',65);const damage=r.success?Math.round((p.power+random(s)*8)*(type==='skill'?1.7:1)*(r.result==='부분 성공'?.6:1)):0;c.hp=Math.max(0,c.hp-damage);text=`${type==='skill'?(p.id==='baekho'?'신력 포효':'음기의 파동'):'공격'} · ${r.result}, 피해 ${damage}.`;if(type==='skill'){p.value=clamp(p.value+(p.id==='jihyo'?7:-4));p.stability=clamp(p.stability-2)}}else if(type==='approach'){c.distance=Math.max(0,c.distance-1);text='거리를 좁히고 상대의 움직임을 읽는다.'}else if(type==='retreat'){c.distance=Math.min(2,c.distance+1);text='뒤로 물러나 거리를 벌린다.'}else if(type==='guard'){c.guard=true;p.energy=clamp(p.energy+8,0,60);text='몸을 낮추고 공격에 대비한다.'}else if(type==='dodge'){r=check(s,'agility',55);c.cover=r.success;text=`회피 · ${r.result}.`}else if(type==='environment'){r=check(s,'insight',65);if(r.success){c.hp=Math.max(0,c.hp-18);c.stunned=true}text=`쓰러진 나무와 바위를 이용한다 · ${r.result}${r.success?', 피해 18 / 적 행동 방해':''}.`}else if(type==='flee'){r=check(s,'agility',c.distance===2?25:65);if(r.success){finish(s,'수풀 사이로 빠져나와 추격을 따돌렸다.');return true}text='퇴로를 막혔다. 도주 실패.'}else if(type==='negotiate'){r=check(s,'will',80);if(r.success){if(c.id)relation(s,c.id,p.id,{hostility:-12,trust:4});finish(s,'서로 한 발 물러났다. 잠시 휴전하기로 한다.');return true}text='상대는 제안을 받아들이지 않는다.'}else if(type==='item'){if(!s.inventory.herb){record(s,'약초가 없습니다.','system');return false}s.inventory.herb--;p.hp=clamp(p.hp+30,0,p.maxHp);text='약초를 사용했다. 체력 30 회복.'}else return false;
record(s,text,'combat',5);if(r)record(s,`판정 ${r.roll} / 성공 기준 ${r.chance} (${r.result})`,'check');if(c.hp<=0){s.inventory.coins+=12;finish(s,'상대가 쓰러져 전투가 끝났다. 전리품 12전을 얻었다. 상대는 기절 상태다.');return true}if(c.stunned){record(s,'적이 자세를 되찾느라 공격하지 못했다.','combat');c.stunned=false}else if(c.distance===2){c.distance=1;record(s,'상대가 거리를 좁힌다.','combat')}else{const dmg=c.cover?0:Math.max(1,Math.round((c.power+random(s)*7)*(c.guard?.35:1)));p.hp=Math.max(0,p.hp-dmg);record(s,`${c.name}의 반격. ${dmg} 피해.`,'combat');}c.guard=false;c.cover=false;c.round++;if(p.hp<=0){p.status='중상';p.hp=1;const lost=Math.min(15,s.inventory.coins);s.inventory.coins-=lost;s.location=s.version===3?'forest':'home';p.location=s.location;if(!s.visited.includes(s.location))s.visited.push(s.location);finish(s,`의식을 잃었다. 한참 뒤 산속 거처에서 눈을 뜬다. 중상 / ${lost}전 분실. 이번 프로토타입의 패배 결과는 구조와 중상이다.`)}return true}
